int solve(vector<int>& a) {
    int n = a.size();
    vector<vector<int>> dp(n, vector<int>(n, 0));
    for (int len = 2; len <= n; len++)              // grow the interval length
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            dp[i][j] = INT_MAX;
            for (int k = i; k < j; k++)             // try every split point
                dp[i][j] = min(dp[i][j],
                               dp[i][k] + dp[k + 1][j] + costToMerge(a, i, k, j));
        }
    return dp[0][n - 1];
}

