function solve(a) {
  const n = a.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let len = 2; len <= n; len++)                // grow the interval length
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      dp[i][j] = Infinity;
      for (let k = i; k < j; k++)                   // try every split point
        dp[i][j] = Math.min(dp[i][j],
                            dp[i][k] + dp[k + 1][j] + costToMerge(a, i, k, j));
    }
  return dp[0][n - 1];
}
